Qnn_ErrorHandle_t mixedNode(Qnn_GraphHandle_t graph,Qnn_OpConfig_t config){auto& c=config.v1;std::string type=c.typeName;bool obs=type.find("NoReceipt")==std::string::npos;auto mat=[](const Qnn_Tensor_t& t,unsigned r,unsigned col){return t.v1.rank==4&&t.v1.dimensions[0]==1&&t.v1.dimensions[1]==1&&t.v1.dimensions[2]==r&&t.v1.dimensions[3]==col&&t.v1.dataType==QNN_DATATYPE_FLOAT_32;};
 if(!std::strcmp(c.packageName,"HexaMixedQkv")||type.rfind("ProjectionQKVHvx",0)==0){if(c.numOfInputs!=4||c.numOfOutputs!=(obs?4u:3u))return 1;for(unsigned i=0;i<4;++i)if(!mat(c.inputTensors[i],i?64:32,64))return 1;for(unsigned i=0;i<3;++i)if(!mat(c.outputTensors[i],32,64))return 1;if(obs&&(c.outputTensors[3].v1.dataType!=QNN_DATATYPE_INT_32||c.outputTensors[3].v1.dimensions[3]!=(!std::strcmp(c.packageName,"HexaMixedQkv")?20512u:20504u)))return 1;return QNN_SUCCESS;}
 if(!std::strcmp(c.packageName,"HexaSelectiveLn1")){if(type!=(obs?"S2":"S2NoReceipt")||c.numOfInputs!=4||c.numOfOutputs!=(obs?4u:3u))return 1;unsigned ir[]={32,1,1,1},ic[]={64,64,64,1};for(unsigned i=0;i<4;++i)if(!mat(c.inputTensors[i],ir[i],ic[i]))return 1;for(unsigned i=0;i<3;++i)if(!mat(c.outputTensors[i],32,i==2?1:64))return 1;if(obs&&c.outputTensors[3].v1.dimensions[3]!=6313)return 1;return QNN_SUCCESS;}
 if(type.rfind("ForwardQKRaw",0)==0){if(c.numOfInputs!=4||c.numOfOutputs!=(obs?3u:2u))return 1;for(unsigned i=0;i<4;++i)if(!mat(c.inputTensors[i],32,32))return 1;for(unsigned i=0;i<2;++i)if(!mat(c.outputTensors[i],32,32))return 1;if(obs&&c.outputTensors[2].v1.dimensions[3]!=6152)return 1;return QNN_SUCCESS;}
 return node(graph,config);
}
int main(){api.graphCreate=create;api.tensorCreateGraphTensor=tensorCreate;api.graphAddNode=mixedNode;api.graphFinalize=finish;unsigned count=0;for(unsigned s=0;s<4;++s)for(bool m:{false,true})for(bool o:{true,false})for(bool t:{true,false}){mixedprobe::Graph z(m,o,t,s);auto& g=z.g;if(g.nodes!=(s==0?1u:s+2u)||g.inputs.size()!=(s?7u:4u))return 1;unsigned receipt=0;for(auto& x:g.tensors)receipt+=x.v1.dataType==QNN_DATATYPE_INT_32;if(receipt!=(o?(s==0?1u:s+2u):0u))return 2;if(s)for(auto id:{z.y,z.h,z.iv})if(g.tensors[id].v1.type!=(t?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE))return 3;for(auto id:z.q)if(g.tensors[id].v1.type!=(s<2||t?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE))return 4;++count;}std::printf("mixed_graph_host=PASS graphs=%u shape=1 native_ownership=1 receipt_absence=1\n",count);}
